from __future__ import annotations

from typing import TYPE_CHECKING, Iterator, cast
from datetime import datetime
import pytz

from docx.shared import Parented
from docx.text.paragraph import Paragraph

if TYPE_CHECKING:
    import docx.types as t
    from docx.oxml.comments import CT_Comment, CT_Comments


class Comments(Parented):
    """A container for comments."""

    def __init__(self, ct_comments: CT_Comments, parent: t.ProvidesCommentsPart):
        super(Comments, self).__init__(parent)
        self._ct_comments = ct_comments

    def add_comment(self, text: str, author: str, author_id: str, date: str = None, timezone: str = None) -> Comment:
        """Add a comment.

        If timezone is specified, the date will be converted to that timezone.
        """
        if date is None:
            date = datetime.utcnow().isoformat() + 'Z'

        if timezone is not None:
            try:
                tz = pytz.timezone(timezone)
                # Parse the date and convert to specified timezone
                if date.endswith('Z'):
                    dt = datetime.fromisoformat(date[:-1]).replace(tzinfo=pytz.UTC)
